// Shared integer series keeps trend totals consistent with the observation snapshot.
export function TrendChart({ period = "24小时" }: { period?: string }) {
  const [hover, setHover] = useState<number | null>(null);
  const uid = useId().replace(/:/g, "");
  const series = observationSeries(period);
  const data = series.map((point) => point.value);
  const negative = series.map((point) => point.negative);
  const width = 720,
    height = 210;
  const max = Math.max(4, Math.ceil(Math.max(...data) / 4) * 4);
  const safeHover = hover === null ? null : Math.min(hover, series.length - 1);
  // All lines share one scale; a negative subset must never exceed its total.
  const path = (values: number[]) =>
    values
      .map(
        (v, i) =>
          `${i ? "L" : "M"}${(i * width) / (values.length - 1)},${height - (v / max) * height}`,
      )
      .join(" ");
  const labelIndexes = [
    ...new Set(
      Array.from({ length: 7 }, (_, i) =>
        Math.round((i * (series.length - 1)) / 6),
      ),
    ),
  ];
  return (
    <div className="trend-chart">
      <div className="chart-unit">
        单位：条 · {period === "24小时" ? "每小时" : "每日"}
      </div>
      <div className="chart-plot">
        <div className="y-labels">
          {[4, 3, 2, 1, 0].map((n) => (
            <span key={n}>{((n * max) / 4).toLocaleString()}</span>
          ))}
        </div>
        <svg
          viewBox={`-2 -3 ${width + 4} ${height + 6}`}
          preserveAspectRatio="none"
          role="img"
          tabIndex={0}
          aria-label={`${period}声量趋势，使用左右方向键查看观察值`}
          onFocus={() => setHover(series.length - 1)}
          onBlur={() => setHover(null)}
          onPointerLeave={() => setHover(null)}
          onKeyDown={(event) => {
            if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
              event.preventDefault();
              setHover(
                Math.max(
                  0,
                  Math.min(
                    series.length - 1,
                    (safeHover ?? series.length - 1) +
                      (event.key === "ArrowLeft" ? -1 : 1),
                  ),
                ),
              );
            }
          }}
          onPointerMove={(event) => {
            const rect = event.currentTarget.getBoundingClientRect();
            setHover(
              Math.max(
                0,
                Math.min(
                  series.length - 1,
                  Math.round(
                    ((event.clientX - rect.left) / rect.width) *
                      (series.length - 1),
                  ),
                ),
              ),
            );
          }}
        >
          <defs>
            <linearGradient id={`fill-${uid}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#527cf1" stopOpacity=".22" />
              <stop offset="100%" stopColor="#527cf1" stopOpacity=".01" />
            </linearGradient>
          </defs>
          {[0, 1, 2, 3, 4].map((i) => (
            <line
              key={i}
              x1="0"
              x2={width}
              y1={(i * height) / 4}
              y2={(i * height) / 4}
              stroke="#e8edf6"
              strokeDasharray="3 5"
            />
          ))}
          <path
            d={`${path(data)} L${width},${height} L0,${height} Z`}
            fill={`url(#fill-${uid})`}
          />
          <path
            d={path(data)}
            stroke="#4c77ed"
            strokeWidth="2.5"
            fill="none"
            strokeLinejoin="round"
          />
          <path
            d={path(negative)}
            stroke="#e8a264"
            strokeWidth="2"
            fill="none"
            strokeLinejoin="round"
          />
          {safeHover !== null && (
            <g>
              <line
                x1={(safeHover * width) / (series.length - 1)}
                x2={(safeHover * width) / (series.length - 1)}
                y1={0}
                y2={height}
                stroke="#a5b6e7"
                strokeDasharray="4 4"
              />
              <circle
                cx={(safeHover * width) / (series.length - 1)}
                cy={height - (data[safeHover] / max) * height}
                r="4"
                fill="#4c77ed"
                stroke="white"
                strokeWidth="2"
              />
            </g>
          )}
        </svg>
        {safeHover !== null && (
          <div
            className="chart-tooltip"
            role="status"
            style={{
              left: `${Math.min(65, Math.max(7, (safeHover / (series.length - 1)) * 85))}%`,
            }}
          >
            {series[safeHover].label}
            <b>观察声量 {data[safeHover].toLocaleString()} 条</b>
            <span>负面表达 {negative[safeHover].toLocaleString()} 条</span>
          </div>
        )}
      </div>
      <div className="x-labels">
        {labelIndexes.map((i) => (
          <span key={i}>{series[i].label}</span>
        ))}
      </div>
    </div>
  );
}

export function SourceDonut() {
  const segments = sourceRows
    .filter((source) => source.count > 0)
    .map((source, i) => ({
      name: source.name,
      count: source.count,
      pct: (source.count / observationTotal) * 100,
      color: ["#4c75ed", "#6fc7cb", "#9ca9ed"][i],
    }));
  let offset = 0;
  return (
    <div className="source-distribution">
      <div className="donut-wrap">
        <svg
          viewBox="0 0 180 180"
          role="img"
          aria-label={segments
            .map((s) => `${s.name} ${s.pct.toFixed(1)}%`)
            .join("，")}
        >
          {segments.map((s) => {
            const start = offset;
            offset += s.pct;
            return (
              <circle
                key={s.name}
                cx="90"
                cy="90"
                r="65"
                fill="none"
                stroke={s.color}
                strokeWidth="19"
                strokeDasharray={`${s.pct * 4.084 - 4} ${408.4 - (s.pct * 4.084 - 4)}`}
                strokeDashoffset={-start * 4.084}
                transform="rotate(-90 90 90)"
              />
            );
          })}
        </svg>
        <div className="donut-label">
          <b>{observationTotal.toLocaleString()}</b>
          <span>采集总量</span>
        </div>
      </div>
      <div className="source-legend">
        {segments.map((s) => (
          <div key={s.name}>
            <span>
              <i style={{ background: s.color }} />
              {s.name}
            </span>
            <b>
              {s.pct.toFixed(1)}
              <small>%</small>
            </b>
          </div>
        ))}
      </div>
    </div>
  );
}

// Both dialogs and drawers share keyboard handling and restore focus after closing.
export function Overlay({
  title,
  subtitle,
  onClose,
  children,
  wide = false,
  modal = false,
}: {
  title: string;
  subtitle?: string;
  onClose: () => void;
  children: ReactNode;
  wide?: boolean;
  modal?: boolean;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const titleId = useId();
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const bodyOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    ref.current?.focus();
    const keydown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "Tab") {
        const elements = ref.current?.querySelectorAll<HTMLElement>(
          'button:not(:disabled),a,input,select,textarea,[tabindex="0"]',
        );
        if (!elements?.length) {
          e.preventDefault();
          return;
        }
        const first = elements[0],
          last = elements[elements.length - 1];
        if (
          e.shiftKey &&
          (document.activeElement === first ||
            document.activeElement === ref.current)
        ) {
          e.preventDefault();
          last.focus();
        } else if (
          !e.shiftKey &&
          (document.activeElement === last ||
            document.activeElement === ref.current)
        ) {
          e.preventDefault();
          first.focus();
        }
      }
    };
    document.addEventListener("keydown", keydown);
    return () => {
      document.body.style.overflow = bodyOverflow;
      document.removeEventListener("keydown", keydown);
      previous?.focus();
    };
  }, [onClose]);
  return (
    <div
      className={`overlay ${modal ? "centered" : ""}`}
      onMouseDown={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div
        className={`${modal ? "modal" : "drawer"} ${wide ? "wide" : ""}`}
        ref={ref}
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        tabIndex={-1}
      >
        <div className="overlay-head">
          <div>
            <h2 id={titleId}>{title}</h2>
            {subtitle && <p>{subtitle}</p>}
          </div>
          <button className="icon-button" aria-label="关闭" onClick={onClose}>
            <X size={21} />
          </button>
        </div>
        <div className="overlay-body">{children}</div>
      </div>
    </div>
  );
}

